python3 -c "
from pptx import Presentation
prs = Presentation('/app/output/final_deck.pptx')
for i, sl in enumerate(prs.slides):
    print(f'\n=== SLIDE {i+1} ===')
    for s in sl.shapes:
        if s.has_text_frame:
            text = s.text_frame.text.strip()
            if text:
                # truncate long text
                if len(text) > 150:
                    text = text[:150] + '...'
                print(f'  [{s.shape_type}] {text}')
        if s.has_chart:
            ch = s.chart
            print(f'  [CHART] type={ch.chart_type}')
            if hasattr(ch, 'plots') and ch.plots:
                plot = ch.plots[0]
                print(f'    series count: {len(plot.series)}')
"

