from pptx import Presentation
prs = Presentation('/app/output/final_deck.pptx')

# Verify Slide 4 chart data (horizontal bar - salary by dev type)
sl4 = prs.slides[3]
for s in sl4.shapes:
    if s.has_chart:
        ch = s.chart
        cats = [str(c) for c in ch.plots[0].categories]
        vals = [v for v in ch.plots[0].series[0].values]
        print('Slide 4 - Salary by Developer Type (BAR_CLUSTERED):')
        for c, v in zip(cats, vals):
            print(f'  {c}: \${v:,.0f}')

# Verify Slide 5 scatter data
sl5 = prs.slides[4]
for s in sl5.shapes:
    if s.has_chart:
        ch = s.chart
        print(f'\nSlide 5 - Experience vs Salary (XY_SCATTER, {len(ch.plots[0].series)} series):')
        for sr in ch.plots[0].series:
            # Get series name and data points
            name = str(sr.format.fill.fore_color.rgb) if sr.format.fill.type is not None else 'N/A'
            try:
                vals = list(sr.values)
                print(f'  Series: x={vals[0]}, y={vals[1]}')
            except:
                pass

# Verify Slide 6 scatter data  
sl6 = prs.slides[5]
for s in sl6.shapes:
    if s.has_chart:
        ch = s.chart
        print(f'\nSlide 6 - Salary by Language (XY_SCATTER, {len(ch.plots[0].series)} series):')
        for sr in ch.plots[0].series:
            try:
                vals = list(sr.values)
                print(f'  Series: x={vals[0]}, y={vals[1]}')
            except:
                pass
"

